from collections import Counter, deque
import json
def comps(g,bg):
    H,W=len(g),len(g[0]);seen=set();out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                v=g[r][c];q=deque([(r,c)]);seen.add((r,c));cells=[]
                while q:
                    x,y=q.popleft();cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==v and (a,b) not in seen:
                            seen.add((a,b));q.append((a,b))
                out.append((v,cells))
    return out
